/* M&A module: lessons, cards and lesson quizzes. Questions follow the Red Book (1st ed.) order; answers are IBZY study notes. */
window.IBZY_CONTENT["mna"] = {"units": {"mna-u1": [{"id": "mna-u1-l1", "title": "Why companies merge & how deals are sold", "pages": "73–74", "cards": [{"id": "mna-u1-1", "q": "Can you define M&A and explain the difference between a merger and an acquisition?", "a": "<p>M&amp;A is the umbrella term for combining two businesses. For buyers it’s an alternative to organic growth; for sellers it’s a way to cash out or share in the combined company’s risk and reward. The terms are often used interchangeably, but:</p><p><b>Merger:</b> usually two similarly sized companies (a “merger of equals”), paid at least partly in stock so both sets of shareholders remain. The combined company often uses a joint name (ExxonMobil, Kraft Heinz, Citigroup) or is renamed.</p><p><b>Acquisition:</b> usually a larger buyer taking over a smaller target. The target’s name often fades as it’s integrated — though sometimes it runs as a subsidiary to keep an established brand (Salesforce–Slack, Google–Fitbit).</p>", "p": 73}, {"id": "mna-u1-2", "q": "What are some potential reasons that a company might acquire another company?", "a": "<ul><li>Value creation from revenue and cost synergies</li><li>Owning technology assets — IP, patents, proprietary tech</li><li>Acquiring talent</li><li>Expanding into new geographies or product/service markets</li><li>Diversifying revenue (less risk, lower cost of capital)</li><li>Getting new products to market faster</li><li>More channels to sell through</li><li>Market leadership and less competition (horizontal deals)</li><li>Supply chain efficiencies (vertical deals)</li><li>Tax benefits, if the target has NOLs</li></ul>", "p": 73}, {"id": "mna-u1-3", "q": "What are the differences among vertical, horizontal, and conglomerate mergers?", "a": "<p><b>Vertical:</b> companies at different stages of the same value chain. More control over the supply chain should, in theory, remove inefficiencies.</p><p><b>Horizontal:</b> direct competitors in the same or very similar market, so competition falls afterwards (e.g. Sprint and T-Mobile). Benefits include wider geographic reach and more pricing power.</p><p><b>Conglomerate:</b> businesses in unrelated industries combined for diversification — Berkshire Hathaway is the example.</p>", "p": 73}, {"id": "mna-u1-4", "q": "In terms of vertical integration, what is the difference between forward and backward integration?", "a": "<p><b>Backward integration</b> (moving upstream): buying suppliers or manufacturers of what the company sells.</p><p><b>Forward integration</b> (moving downstream): buying something closer to the end customer, such as a distributor or a technical support business.</p>", "p": 73}, {"id": "mna-u1-5", "q": "Describe a recent M&A deal.", "a": "<p>Have at least one recent deal ready to discuss in detail. Read the press releases and credible commentary to understand the rationale and how the market reacted, and look at the competitive dynamics and trends in the industries involved.</p><p>Cover:</p><ul><li>the acquirer and target, with a short profile of each;</li><li>whether it’s a merger or an acquisition;</li><li>the strategic rationale (from the S-4 or the announcement);</li><li>approximate size, premium offered and form of consideration, if disclosed;</li><li>how both share prices moved after the announcement;</li><li>your own view — was it a good deal?</li></ul>", "p": 74}, {"id": "mna-u1-6", "q": "What are synergies and why are they important in a deal?", "a": "<p>Synergies are the extra revenue or cost savings expected from combining two companies. They matter because if the buyer believes it can realise them, it can justify paying a higher premium.</p><p><b>Revenue synergies:</b> cross-selling and upselling, bundling, new distribution channels, geographic expansion, access to new end markets, and more pricing power from reduced competition.</p><p><b>Cost synergies:</b> removing overlapping staff, closing or consolidating redundant facilities, streamlining processes, more purchasing power over suppliers, and tax savings (e.g. NOLs).</p>", "p": 74}, {"id": "mna-u1-7", "q": "Why should companies acquired by strategic acquirers expect to fetch higher premiums than those selling to private equity buyers?", "a": "<p>Strategic buyers can usually capture <b>synergies</b>, which lets them pay more. That gap has narrowed, though: PE firms increasingly make add-on acquisitions for an existing portfolio (platform) company, which can capture synergies much like a strategic — so financial buyers can now bid more competitively in auctions.</p>", "p": 74}, {"id": "mna-u1-8", "q": "How do you perform premiums paid analysis in M&A?", "a": "<p>Bankers advising a public target look at the premiums paid in comparable past transactions. The average historical premium serves as a reference point — a sanity check for the premium the target should expect in the current deal.</p>", "p": 74}, {"id": "mna-u1-9", "q": "Tell me about the two main types of auction structures in M&A.", "a": "<p><b>Broad auction:</b> the sell-side bank contacts as many potential buyers as possible. More competition means a higher price, so casting a wide net maximises the chance of the best offer and avoids leaving money on the table.</p><p><b>Targeted auction:</b> the bank (usually at the client’s direction) approaches a shortlist of buyers — those with a strong strategic fit or an existing relationship with the seller.</p>", "p": 74}]}, {"id": "mna-u1-l2", "title": "Deal value, documents & protections", "pages": "75–76", "cards": [{"id": "mna-u1-10", "q": "What is a negotiated sale?", "a": "<p>A sale process involving only a handful of buyers — best when the seller has a specific buyer in mind, for example because the owner plans to stay on and values the partnership and growth opportunities. It’s faster and more confidential, negotiated privately and usually on friendlier terms.</p>", "p": 75}, {"id": "mna-u1-11", "q": "What are some of the most common reasons that M&A deals fail to create value?", "a": "<ul><li><b>Overpaying / overestimating synergies:</b> almost every deal involves a premium, and even a deal that goes well may not justify it. Synergies are hard to achieve and should be estimated conservatively — but being conservative can mean getting outbid, so buyers often accept that the synergies justifying the price may not fully materialise.</li><li><b>Inadequate due diligence:</b> focusing on the target’s positives and post-deal benefits while neglecting the risks — especially in a competitive auction with a short timeline where rival bidders are a distraction.</li><li><b>No strategic plan:</b> chasing scale and resources without a real strategy, so synergies never materialise despite the opportunities.</li><li><b>Poor integration:</b> weak leadership after closing leads to low morale, culture clashes and falling product or service quality. Cultural fit is often the hardest risk to judge.</li></ul>", "p": 75}, {"id": "mna-u1-12", "q": "Studies have repeatedly shown a high percentage of deals destroy shareholder value. If that's the case, why do companies still engage in M&A?", "a": "<p>Many deals are done out of <b>necessity</b> — defensive moves to protect market share or keep up with competitors. Once a company has a large share of its market, its focus shifts from stealing share to protecting it, because now it’s the incumbent everyone is targeting.</p><p>So it has to watch for emerging trends and up-and-coming companies that could become threats, and keep up with new technology. M&amp;A is a way to neutralise outside threats and acquire new capabilities — often a defensive response to structural disruption in the sector.</p>", "p": 75}, {"id": "mna-u1-13", "q": "What is the purpose of a teaser?", "a": "<p>A one- to two-page marketing document the sell-side bank sends potential buyers first, to gauge interest. The goal is to get them interested enough to sign an NDA and receive the confidential information memorandum (CIM).</p><p>It’s anonymous — the company is called something like “Project [Name]” — and includes only a brief business description, investment highlights and summary financials (e.g. revenue, operating income and EBITDA for the last 2–3 years): just enough for a buyer to understand the business and decide whether to proceed.</p>", "p": 75}, {"id": "mna-u1-14", "q": "What does a confidential information memorandum (CIM) consist of?", "a": "<p>The CIM is an in-depth overview of the business for sale, sent to buyers after they sign an NDA. Typically 20–50 pages, it covers: a detailed company profile, market overview and industry trends, investment highlights, business segments and products/services, historical summary financials, management’s projections (the “Management Case”), management bios, and the transaction details and timeline.</p>", "p": 76}, {"id": "mna-u1-15", "q": "What are the typical components found in a letter of intent (LOI)?", "a": "<p>An LOI is the buyer’s formal letter setting out its proposed initial terms: the <b>purchase price</b>, the <b>form of consideration</b> and the planned <b>financing sources</b>. It’s usually non-binding — a preview of what a definitive agreement could look like, with room for further negotiation.</p>", "p": 76}, {"id": "mna-u1-16", "q": "What are “no-shop” provisions in M&A deals?", "a": "<p>The “no solicitation” or no-shop clause protects the buyer by giving it exclusivity during negotiations: the seller’s side can’t seek higher bids or use the buyer’s offer to drum up other bidders. Breaching it triggers a significant break-up fee, and the sell-side bank would be investigated.</p><p>Sellers protect themselves with a <b>reverse termination fee (RTF)</b>, which the buyer pays if it walks away from the deal.</p>", "p": 76}, {"id": "mna-u1-17", "q": "What is a material adverse change (MAC), and could you provide some examples?", "a": "<p>A MAC clause is a heavily negotiated legal provision, found in virtually every merger agreement, that manages risk between signing and closing. It lists the conditions under which the buyer can walk away without legal penalties or major fees. Common triggers:</p><ul><li>major changes in economic, financial, credit or capital market conditions;</li><li>relevant changes like new regulations, GAAP changes or deal litigation (e.g. antitrust);</li><li>natural disasters or geopolitical events (hostilities, war, terrorism);</li><li>failure to hit agreed revenue, earnings or other financial targets.</li></ul>", "p": 76}]}, {"id": "mna-u1-l3", "title": "Deal structures & hostile takeovers", "pages": "77–79", "cards": [{"id": "mna-u1-18", "q": "Contrast asset sales vs. 338(h)(10) election vs. stock sales.", "a": "<table><tr><th>Type</th><th>How it works</th><th>Tax implications</th></tr><tr><td><b>Asset sale</b></td><td>The seller sells each asset to the buyer under contract. Owning all the assets, the buyer controls everything that made the seller’s equity valuable.</td><td>Buyer gets a <b>step-up</b> in the tax basis of the assets, creating tax-deductible D&amp;A and future cash tax savings. Seller may be taxed twice — at the corporate and shareholder level.</td></tr><tr><td><b>Stock sale</b></td><td>The seller hands over its shares; owning all of them, the buyer controls the business.</td><td>No step-up, so no extra deal-related D&amp;A tax savings for the buyer. Seller is taxed only once, at the shareholder level.</td></tr><tr><td><b>338(h)(10) election</b></td><td>A joint election by buyer and seller: legally a stock sale, but treated as an asset sale for tax — without transferring assets one by one. Applies to corporate subsidiaries and S-corps; most useful when the target has large NOLs.</td><td>Stock-sale simplicity plus asset-sale tax benefits. Seller still faces double taxation, but the buyer gets the step-up (and NOLs), which can support a higher price.</td></tr></table>", "p": 77}, {"id": "mna-u1-19", "q": "Contrast a friendly acquisition and hostile takeover attempt.", "a": "<p><b>Friendly:</b> both companies’ management teams and boards agree to negotiate and reach terms. The target’s board tells shareholders about the bid and its recommendation, and shareholders usually follow the board.</p><p><b>Hostile:</b> usually follows a failed friendly approach. The target’s management and board oppose the deal, but the acquirer keeps pursuing a majority stake by going directly to shareholders.</p>", "p": 77}, {"id": "mna-u1-20", "q": "What are the two most common ways that hostile takeovers are pursued?", "a": "<p><b>Tender offer:</b> the acquirer publicly offers to buy shares from existing shareholders at a premium, aiming to collect enough voting shares to control the company and push the deal through.</p><p><b>Proxy fight:</b> the acquirer tries to persuade shareholders to vote out the current management and board, usually by arguing the company is being mismanaged, so it can take control.</p>", "p": 77}, {"id": "mna-u1-21", "q": "How does a tender offer differ from a merger?", "a": "<p>A <b>tender offer</b> is a public bid to buy some or all of a company’s shares directly from shareholders at a price above the market — often used in hostile situations to gain control without management and board approval.</p><p>A <b>merger</b> is negotiated jointly between the two companies, who agree to combine.</p>", "p": 78}, {"id": "mna-u1-22", "q": "What are some preventive measures used to block a hostile takeover attempt?", "a": "<ul><li><b>Poison pill:</b> existing shareholders get the right to buy extra shares at a discount, diluting the acquirer and making a majority stake much harder to reach.</li><li><b>Golden parachute:</b> key executives’ packages are enhanced with generous severance and benefits (insurance, pensions) if they’re removed after a takeover — which a hostile acquirer would likely do, so it raises the cost.</li><li><b>Dead hand provision:</b> like a poison pill, but extra shares are issued automatically to every shareholder except the acquirer.</li><li><b>Crown jewel defence:</b> an arrangement to sell the company’s most valuable assets (patents, IP, trade secrets) if it’s taken over, making it much less attractive.</li></ul>", "p": 78}, {"id": "mna-u1-23", "q": "What are some active defense measures to block a hostile takeover attempt?", "a": "<ul><li><b>White knight:</b> a friendly buyer acquires the target instead of the hostile bidder (the “black knight”), usually as a last resort. The target loses independence but on better terms.</li><li><b>White squire:</b> a friendly investor buys only a partial stake — big enough to block the hostile bid — so the target keeps control.</li><li><b>Acquisition defence:</b> the target makes an acquisition of its own, even paying a premium, so its balance sheet (less cash, more debt) becomes less appealing.</li><li><b>Pac-Man defence:</b> the target tries to buy the hostile acquirer — mainly as a deterrent and last resort, not something it wants to complete.</li><li><b>Greenmail:</b> an acquirer builds a large stake and threatens a takeover unless the target buys its shares back at a big premium. Anti-greenmail rules have made this almost impossible today.</li></ul>", "p": 78}, {"id": "mna-u1-24", "q": "What is a staggered board and how does it fend off hostile takeover attempts?", "a": "<p>In a staggered board, directors are split into classes with different term lengths, so only some seats come up for election each year. A hostile acquirer can’t replace the whole board in one go — winning control takes several election cycles, which slows and discourages takeover attempts and protects the existing board and management.</p>", "p": 79}]}, {"id": "mna-u1-l4", "title": "Divestitures, filings & deal mechanics", "pages": "79–80", "cards": [{"id": "mna-u1-25", "q": "What is a divestiture and why would one be completed?", "a": "<p>A divestiture is the sale of a business segment and its assets. It usually happens when management decides a segment doesn’t add enough value to the core — it’s redundant, a distraction or doesn’t fit with other divisions. Selling it cuts costs, sharpens focus on the core business and can let the divested unit run leaner and unlock hidden value.</p><p>Other drivers include restructuring (avoiding insolvency) or regulatory pressure to prevent a monopoly.</p><p>Investors may see it as an admission of a failed strategy — the unit didn’t deliver expected benefits like economies of scale — or as a sign the company needs cash to reinvest or shore up liquidity. Many divestitures are pushed by activist investors, who then ask for the proceeds to be returned to shareholders.</p>", "p": 79}, {"id": "mna-u1-26", "q": "How does an equity carve-out differ from a divestiture?", "a": "<p>An equity carve-out, often called a “partial IPO”, is when the parent sells <b>part</b> of its stake in a subsidiary to public investors — almost always keeping a large stake (usually over 50%). The subsidiary becomes a separate legal entity with its own management and board. The cash raised goes to the parent, the subsidiary, or both. A divestiture, by contrast, sells the business outright.</p>", "p": 79}, {"id": "mna-u1-27", "q": "What is a spin-off and why are they completed?", "a": "<p>In a spin-off, the parent separates a division into an independent company with its own shares, which are distributed <b>pro rata</b> to existing shareholders. Each shareholder then decides whether to keep or sell them. No cash changes hands. Spin-offs usually respond to shareholder pressure to separate a subsidiary that would do better on its own.</p>", "p": 79}, {"id": "mna-u1-28", "q": "What is the difference between a subsidiary and an affiliate company?", "a": "<p><b>Subsidiary:</b> the parent owns a majority (over 50%).</p><p><b>Affiliate:</b> the parent owns only a minority stake.</p>", "p": 79}, {"id": "mna-u1-29", "q": "What is a reverse merger and what benefits does it provide?", "a": "<p>A private company merges into a company that’s already publicly listed — either an operating business or an empty shell. The combined company is public, so it can issue shares without the cost and process of an IPO.</p>", "p": 79}, {"id": "mna-u1-30", "q": "What is an S-4 filing and when does it have to be filed?", "a": "<p>An S-4 must be filed with the SEC before an M&amp;A transaction involving the issuance of securities takes place. It contains the material information about the deal: the rationale, negotiated terms, risk factors, pro forma financials and related details.</p>", "p": 80}, {"id": "mna-u1-31", "q": "What is the difference between the Schedule 13-D and 13-G filing?", "a": "<p>Both disclose that an investor has taken a significant ownership and voting stake in a public company (a “beneficial owner”).</p><p><b>Schedule 13-D:</b> required when an investor holds at least 5% of a company’s common equity and acquired more than 2% in the last twelve months. It’s due within ten days and must state whether the investor intends to buy more and seek influence.</p><p><b>Schedule 13-G:</b> a shorter alternative for investors with 5%+ who <b>don’t</b> intend to take control (and bought less than 2% in the last year). Requirements depend on the investor type (institutional, passive, etc.). If the investor’s intent changes, it must file a 13-D within ten days.</p>", "p": 80}, {"id": "mna-u1-32", "q": "Can you explain what the “winner’s curse” is in M&A?", "a": "<p>The tendency for the winning bidder to have paid well above the target’s fair value. Some premium is expected in a competitive process, but bidding can escalate to irrational levels. The buyer may later regret it and face criticism — especially if the deal underperforms and acquired assets are written down. For financial buyers, a higher entry multiple makes it harder to hit the fund’s target returns.</p>", "p": 80}, {"id": "mna-u1-33", "q": "What is a holdback in M&A?", "a": "<p>A holdback places part of the purchase price in <b>escrow</b> after closing to protect the buyer. It makes sure the seller fulfils all the agreed conditions; if the seller breaches the terms, the funds can be released to the buyer, limiting its losses.</p>", "p": 80}, {"id": "mna-u1-34", "q": "What type of material is found in an M&A pitchbook?", "a": "<p>A pitchbook is a bank’s marketing document to win a mandate. Contents vary by bank, but a typical M&amp;A pitchbook includes:</p><ul><li>an introduction to the bank and the deal team;</li><li>a situation overview of the client and potential deal;</li><li>current market and industry trends;</li><li>an implied valuation range and combined M&amp;A model;</li><li>the proposed deal strategy and key considerations;</li><li>credentials and tombstones from relevant past deals;</li><li>an appendix (DCF, trading comps, transaction comps).</li></ul>", "p": 80}]}], "mna-u2": [{"id": "mna-u2-l1", "title": "The M&A model & paying with cash or stock", "pages": "81–83", "cards": [{"id": "mna-u2-1", "q": "Walk me through a simple M&A model.", "a": "<p>An M&amp;A model combines two companies into one.</p><ol><li><b>Uses of funds:</b> assume the purchase price plus other uses — refinancing the target’s debt, transaction fees and financing fees.</li><li><b>Sources of funds:</b> decide how it’s paid for — the acquirer’s cash, new debt, new equity or a mix.</li><li><b>Combine the balance sheets.</b> Some lines (e.g. working capital) just add together; others need work. The big adjustment is calculating the new goodwill, which requires assumptions about asset write-ups and deferred taxes created or eliminated. Then reflect the new borrowing and debt paydown, cash used, and elimination of the target’s equity.</li><li><b>Combine the income statements</b> to get pro forma EPS and answer the key question: is the deal <b>accretive or dilutive</b>?</li></ol>", "p": 81}, {"id": "mna-u2-2", "q": "What are two ways to determine the accretive/dilutive impact to EPS?", "a": "<p><b>Bottom-up:</b> start from each company’s standalone net income/EPS and adjust for the deal — add synergies, subtract new interest expense and extra D&amp;A from asset write-ups, and add the new shares issued.</p><p><b>Top-down:</b> combine the two income statements line by line from revenue downwards, making the deal adjustments along the way.</p>", "p": 81}, {"id": "mna-u2-3", "q": "What does accretion/dilution analysis tell you about the attractiveness of a transaction?", "a": "<p>Less than people think. An accretive deal doesn’t necessarily create value, and a dilutive one doesn’t necessarily destroy it.</p><p>But buyers — especially public ones — treat big accretion or dilution as a signal of how investors will react. Many fear dilutive deals because investors may apply the old P/E to the now-lower EPS, pushing the share price down.</p><p>That’s a fair short-term worry about hitting EPS targets, but long-term value creation depends on the <b>intrinsic value</b> of the combined company, not near-term EPS.</p><ul><li><b>Accretive:</b> pro forma EPS &gt; acquirer’s standalone EPS</li><li><b>Dilutive:</b> pro forma EPS &lt; acquirer’s standalone EPS</li><li><b>Breakeven:</b> no change</li></ul>", "p": 81}, {"id": "mna-u2-4", "q": "What does it mean when a transaction is done on a “cash-free, debt-free” basis?", "a": "<p>Almost all deals are negotiated cash-free, debt-free (CFDF). It assumes the seller pays off all outstanding debt and takes out all <b>excess</b> cash (cash above the minimum needed to run the business, after debt is repaid) before closing.</p><p>Since the buyer neither assumes the debt nor gets the cash, it’s effectively paying for the company’s <b>enterprise value</b>.</p>", "p": 82}, {"id": "mna-u2-5", "q": "Is it better to finance a deal via debt or stock?", "a": "<p><b>Buyer’s view:</b> if the buyer’s P/E is well above the target’s, a stock deal will be accretive, which can tip the decision towards stock. For debt, what matters is access to financing and its cost, plus the effect on the capital structure, credit rating and credit statistics.</p><p><b>Seller’s view:</b> most sellers prefer cash unless deferring tax is a priority. Stock is most acceptable in deals closer to a merger of equals, and when the buyer is a public company whose shares are seen as a relatively stable currency.</p>", "p": 82}, {"id": "mna-u2-6", "q": "What does purchase consideration refer to in M&A?", "a": "<p>It’s how the acquirer pays the target’s shareholders — cash, stock or a mix. Two things drive shareholders’ view of an offer:</p><p><b>Tax:</b> an all-cash deal is immediately taxable. An all-stock deal (swapping into shares of the combined company) doesn’t trigger tax at that point.</p><p><b>Outlook:</b> if shareholders are pessimistic about the combined company, they’ll want cash even if it means paying tax now. If they expect the shares to do well, they’ll accept stock to share in the upside.</p>", "p": 82}, {"id": "mna-u2-7", "q": "What is an exchange ratio and what are the two main types?", "a": "<p>In stock (or part-stock) deals, the offer is set using an exchange ratio:</p><p><b>Fixed exchange ratio:</b> a set number of acquirer shares for each target share. The number of shares target holders get — and their ownership of the combined company — stays the same whatever happens to the share price after signing. Target shareholders bear the risk of the acquirer’s shares falling, with no protection.</p><p><b>Floating exchange ratio:</b> a set <i>dollar value</i> per target share, paid in acquirer shares. If the acquirer’s price falls, more shares are issued, so target shareholders are protected on the downside.</p>", "p": 82}, {"id": "mna-u2-8", "q": "When might an acquirer prefer to pay for a target company using stock over cash?", "a": "<p><b>For the acquirer:</b> stock preserves cash. A buyer short on cash can avoid taking on debt to fund the deal.</p><p><b>For the seller:</b> stock lets them share in the business’s future growth and defer tax on the gain from the sale.</p>", "p": 83}, {"id": "mna-u2-9", "q": "Why might some shareholders prefer cash compensation rather than stock?", "a": "<p>Cash is tangible and its value is guaranteed at closing. More risk-averse shareholders, or those who don’t think much of the combined company’s prospects, will prefer it. Others prefer stock to share in the upside and delay paying tax.</p>", "p": 83}]}, {"id": "mna-u2-l2", "title": "Accretion/dilution, offer value & deal adjustments", "pages": "83–84", "cards": [{"id": "mna-u2-10", "q": "Would you expect an all-cash or all-stock deal to result in a higher valuation?", "a": "<p>Usually an <b>all-cash</b> deal comes at a higher valuation. In an all-stock deal, the target’s shareholders keep exposure to the upside of the combined company, so they’ll accept a lower headline price. All-cash proceeds are fixed and capped — no further upside — so sellers want more for them.</p>", "p": 83}, {"id": "mna-u2-11", "q": "In all-stock deals, how can you determine whether an acquisition will be accretive or dilutive?", "a": "<p>Compare P/E ratios:</p><ul><li>If the acquirer’s P/E is <b>lower</b> than the target’s, the deal is <b>dilutive</b> — the acquirer has to issue relatively many shares for each dollar of earnings it buys, so pro forma EPS falls.</li><li>If the acquirer’s P/E is <b>higher</b> than the target’s (including the premium), the deal is <b>accretive</b>.</li></ul><p>(Ignoring synergies and other adjustments.)</p>", "p": 83}, {"id": "mna-u2-12", "q": "Assume that a company is trading at a forward P/E of 20x and acquires a company trading at a forward P/E of 13x. If the deal is 100% stock-for-stock and a 20% premium was paid, will the deal be accretive in year 1?", "a": "<p><b>Yes.</b> In a stock-for-stock deal, it’s accretive whenever the acquirer’s P/E is higher than the P/E it pays for the target.</p><p>Don’t get thrown by the premium: 13x × 1.2 = <b>15.6x</b>, still well below the acquirer’s 20x.</p>", "p": 83}, {"id": "mna-u2-13", "q": "How do you calculate the offer value in an M&A deal?", "a": "<p>Offer value is the price paid for the target’s equity: the offer price per share times the fully diluted share count (including options and convertible securities).</p><div class=\"formula\">Offer value = Fully diluted shares outstanding × Offer price per share</div>", "p": 83}, {"id": "mna-u2-14", "q": "Why is a “normalized” share price used when calculating the offer value?", "a": "<p>News or rumours of a deal often leak and move the share price before it’s announced. The latest price may already reflect the market’s view of the deal, so it doesn’t show the target’s true standalone value. A normalised, “unaffected” price strips that out.</p>", "p": 83}, {"id": "mna-u2-15", "q": "How do you calculate the control premium in an M&A model?", "a": "<p>Compare the offer price with the <b>unaffected</b> share price — the price before any deal news or rumours reached the market.</p><div class=\"formula\">Control premium = (Offer price per share ÷ Unaffected share price − 1) × 100</div>", "p": 84}, {"id": "mna-u2-16", "q": "How do you calculate the transaction value?", "a": "<p>Transaction value is the target’s implied enterprise value at the offer price:</p><div class=\"formula\">Transaction value = Offer value + Target net debt</div>", "p": 84}, {"id": "mna-u2-17", "q": "What are the most common balance sheet adjustments in an M&A model?", "a": "<p>Some lines simply add together; others need deal adjustments.</p><p><b>Accounting side</b></p><ul><li><b>Goodwill:</b> eliminate the target’s old goodwill and create new goodwill from this deal.</li><li><b>PP&amp;E and intangibles:</b> write up to fair market value.</li><li><b>DTLs:</b> create new deferred tax liabilities in a stock sale.</li><li><b>Target equity:</b> eliminated on consolidation.</li></ul><p><b>Funding side</b></p><ul><li><b>Debt:</b> add new acquirer debt (if used) and eliminate target debt — usually refinanced, though occasionally it carries over.</li><li><b>Equity:</b> increase acquirer equity by any new shares issued.</li><li><b>Cash:</b> reduce by cash used to fund the deal and pay fees — transaction fees reduce equity, financing fees reduce new debt.</li></ul>", "p": 84}, {"id": "mna-u2-18", "q": "What are the most common income statement adjustments in an M&A model?", "a": "<ul><li><b>Revenue:</b> add revenue synergies.</li><li><b>Operating expenses:</b> reduce by cost synergies.</li><li><b>Incremental D&amp;A:</b> asset write-ups create more D&amp;A.</li><li><b>Transaction fees:</b> expensed.</li><li><b>Interest expense:</b> up for new acquisition debt; target interest eliminated if its debt is refinanced.</li><li><b>Financing fees:</b> amortised over the debt’s term, as a non-cash charge within interest expense.</li><li><b>Interest income:</b> down, reflecting the cash used in the deal.</li><li><b>Taxes:</b> tax-effect all of the above at the acquirer’s rate.</li><li><b>Pro forma share count:</b> acquirer’s existing shares plus new shares issued.</li></ul>", "p": 84}]}, {"id": "mna-u2-l3", "title": "Goodwill, synergies & fees", "pages": "85–86", "cards": [{"id": "mna-u2-19", "q": "What does a goodwill impairment tell you about a deal?", "a": "<p>Companies must periodically reassess the value of past acquisitions. An impairment means the acquirer now thinks the business is worth <b>less than it paid</b>.</p><p>Example: an acquirer paid $100m for a business, $40m of which was goodwill. If it now values the business at $70m, it recognises a <b>$30m</b> goodwill impairment (reducing retained earnings via the income statement), cutting goodwill to $10m.</p>", "p": 85}, {"id": "mna-u2-20", "q": "Which balance sheet items are often adjusted to fair market value in a transaction?", "a": "<p><b>PP&amp;E</b> and <b>intangible assets</b>. Both are often carried at book values well below market value, so they’re the assets written up the most in a deal.</p>", "p": 85}, {"id": "mna-u2-21", "q": "Who determines the value of fair market write-ups in a transaction?", "a": "<p>Independent appraisers, accountants and specialist valuation firms help determine the write-up amounts.</p>", "p": 85}, {"id": "mna-u2-22", "q": "What is the purpose of a fairness opinion in the M&A context?", "a": "<p>A fairness opinion is provided by the seller’s investment bank to the seller’s board, stating that the deal terms are fair from a third-party perspective. Its purpose is to give the selling shareholders an independent, unbiased assessment of the transaction.</p>", "p": 85}, {"id": "mna-u2-23", "q": "Would an acquirer prefer $100 in revenue synergies or $100 in cost synergies?", "a": "<p><b>Cost synergies.</b> Cost savings drop straight to the bottom line (after tax). Revenue synergies come with costs attached, so less of each dollar reaches profit.</p><p>Example with a 40% pre-tax margin and 25% tax rate:</p><ul><li>$100 revenue synergies → $100 × 40% × (1 − 25%) = <b>$30</b> of net income</li><li>$100 cost synergies → $100 × (1 − 25%) = <b>$75</b> of net income</li></ul>", "p": 85}, {"id": "mna-u2-24", "q": "Are acquirers more likely to achieve revenue synergy or cost synergy expectations?", "a": "<p><b>Cost synergies</b>, though both often fall short. Cost synergies come from specific, controllable actions — cutting headcount, closing facilities. Revenue synergies rely on broader, more uncertain assumptions about cross-selling, new product launches and other growth initiatives.</p>", "p": 85}, {"id": "mna-u2-25", "q": "For investment bankers, why is a sell-side process typically shorter than a buy-side assignment?", "a": "<p>Once an owner decides to sell, finding a group of interested buyers is usually straightforward, so sell-side mandates are more likely to end in a completed deal.</p><p>Buy-side work is different: many companies regularly explore potential targets as market research or to “test the waters”. Those mandates can drag on for months and often end with no transaction.</p>", "p": 85}, {"id": "mna-u2-26", "q": "What is the accounting for transaction fees in M&A?", "a": "<p>Transaction fees — investment banking advisory, accounting and legal fees — are <b>expensed</b> as incurred, which reduces pro forma net income and EPS.</p>", "p": 86}, {"id": "mna-u2-27", "q": "What is the accounting treatment for financing fees?", "a": "<p>Fees for raising acquisition debt aren’t expensed upfront. They’re <b>capitalised and amortised</b> over the life of the debt, creating an ongoing amortisation charge that reduces pro forma net income and EPS over the borrowing term.</p><p>On the balance sheet they’re deducted directly from the debt as a contra-liability (“debt issuance costs”). In a model, the amortisation is a non-cash expense embedded in interest expense.</p>", "p": 86}]}, {"id": "mna-u2-l4", "title": "D&A, NOLs, deferred taxes & earn-outs", "pages": "86–87", "cards": [{"id": "mna-u2-28", "q": "What are some standard income statement adjustments related to a transaction?", "a": "<ul><li>Expected synergies</li><li>Amortisation of capitalised financing fees</li><li>Incremental D&amp;A from write-ups</li><li>Additional interest expense on new debt</li><li>Lost interest income on cash used</li></ul>", "p": 86}, {"id": "mna-u2-29", "q": "What causes incremental D&A to be recorded in M&A deals?", "a": "<p><b>Asset write-ups.</b> When the target’s assets — usually PP&amp;E and intangibles — are written up to fair value, there’s more to depreciate and amortise. The extra D&amp;A reduces pro forma net income and EPS.</p>", "p": 86}, {"id": "mna-u2-30", "q": "What is the impact of target NOLs in M&A?", "a": "<p>It depends on the structure. The acquirer can take over the target’s NOLs, but its annual use is capped — at the purchase price × the long-term tax-exempt rate.</p><p>Alternatively, the target’s NOLs can offset the seller’s gain on sale. Since the 2017 tax reform, that offset is capped at 80% of the target’s taxable income.</p>", "p": 86}, {"id": "mna-u2-31", "q": "Why are deferred tax liabilities (DTLs) created in transactions?", "a": "<p>Because of asset write-ups. In an acquisition, the target’s assets are written up to fair value for <b>book</b> purposes. But in a stock sale, the <b>tax</b> basis usually isn’t stepped up to match.</p><p>So from the deal date, book depreciation on those assets will be higher than tax depreciation — book taxes will be lower than cash taxes owed, and a DTL is created to reflect that.</p>", "p": 86}, {"id": "mna-u2-32", "q": "What happens to a target’s existing NOLs in transactions?", "a": "<p><b>Asset sale:</b> the target can use its NOLs to offset its corporate-level gain on the sale. Any NOLs left over are lost — the acquirer doesn’t get them.</p><p><b>Stock sale:</b> the acquirer can use them in the future, subject to the annual <b>Section 382 limitation</b>: the published long-term tax-exempt rate × the equity purchase price.</p>", "p": 86}, {"id": "mna-u2-33", "q": "An M&A deal has an adjustment for a deferred revenue write-down. Why would this occur?", "a": "<p>It’s common in software deals (e.g. Adobe buying Marketo or Magento), where revenue comes from long-term subscription contracts. In the deal, the target’s deferred revenue is revalued to fair value — and written down if it’s worth less than what’s on the books.</p><p>Causes include doubts about collectability, terminated or breached contracts, or changes in contract terms (upgrades, maintenance, support), which all require re-estimating the remaining performance obligation, the cost of fulfilling it and the appropriate margin on it.</p>", "p": 87}, {"id": "mna-u2-34", "q": "What is an earnout in the context of M&A?", "a": "<p>An earn-out is a contractual arrangement where part of the purchase price (occasionally all of it) is paid later, <b>only if the business hits agreed financial targets</b>. Its formal name is contingent consideration.</p><p>It’s used to break a valuation deadlock: the seller wants a higher price than the buyer is willing or able to pay. Part of the price is deferred and paid only if specific milestones are reached within a set time.</p>", "p": 87}, {"id": "mna-u2-35", "q": "Which side do you believe an earn-out helps more: the buyer or seller?", "a": "<p>Generally the <b>buyer</b>. The seller takes on the risk of underperformance, and the seller’s incentives line up with the buyer’s, since it will work hard to hit the milestones and collect the full price.</p><p>Sellers are usually reluctant because payment is uncertain — but without the earn-out, the valuation gap would often have killed the deal. If the targets are met, the seller can receive all or nearly all of what it originally asked; if not, the buyer avoided overpaying. In short, an earn-out is a <b>risk-allocation</b> tool: payment is deferred and the burden of hitting the targets sits with the seller.</p>", "p": 87}]}, {"id": "mna-u2-l5", "title": "Earn-outs in practice, seller notes & WC pegs", "pages": "87–89", "cards": [{"id": "mna-u2-36", "q": "How are earn-outs typically structured?", "a": "<p>They’re heavily negotiated, but most last <b>1–5 years</b> and pay out in instalments rather than a lump sum, with percentage-based tiers each year that add up to the total earn-out. The two common payoff structures:</p><ul><li><b>Pro rata:</b> the seller is paid for each tier achieved, plus a proportional amount based on how close it came to the next target.</li><li><b>All-or-nothing:</b> no payment for a tier unless its target is met in full — more risk and pressure on the seller.</li></ul>", "p": 87}, {"id": "mna-u2-37", "q": "For earn-outs, why is EBITDA the most common metric to use as the target?", "a": "<p>Most valuations are quoted as a multiple of EBITDA, so it ties neatly to price. If the seller thinks its $1m-EBITDA business is worth 5.0x but the buyer will only pay 4.0x, they can agree $4m upfront plus up to $1m more if an EBITDA goal is hit.</p><p>EBITDA also balances growth and profitability and needs a long-term approach to achieve — a better proxy for real value creation.</p><ul><li><b>Revenue</b> targets can encourage short-term, risky decisions just to hit sales numbers.</li><li><b>Net income</b> is too easy to manipulate (cutting costs or capex, selling assets).</li></ul>", "p": 88}, {"id": "mna-u2-38", "q": "How would an earn-out be modeled on the three statements?", "a": "<p>It doesn’t appear in Sources &amp; Uses (nothing has been paid yet), but both sides’ returns models include it as a contingency.</p><p><b>IS:</b> changes in the estimated value of the contingent payment run through non-operating gains/(losses). A gain means a payout has become less likely; a loss means more likely.</p><p><b>BS:</b> recorded as a contingent consideration liability at fair value on the acquisition date — the present value of the probability-weighted expected payment, set by an accountant. It’s remeasured periodically as targets are hit or missed, until the earn-out period ends.</p><p><b>CFS:</b> an actual payout is recorded when a target is met. The fair value changes are non-cash, so they’re adjusted for, unlike the real cash payout.</p>", "p": 88}, {"id": "mna-u2-39", "q": "Which industries would you expect earnouts to be the more prevalent?", "a": "<p><b>Healthcare.</b> Heavy regulation and strict compliance requirements mean buyers have to manage a lot of risk, and the FTC and DOJ have increased scrutiny of healthcare M&amp;A. Add the uncertainty of products still in development and trials, and the value of many targets depends on future events nobody can predict.</p><p>So many healthcare deals include contingencies tied to regulatory approval. Uniquely to the sector, earn-outs are often triggered by events like FDA approval or classification, patent approvals, or a sequence of milestones (approval, then production targets, then sales targets).</p>", "p": 88}, {"id": "mna-u2-40", "q": "In M&A, what is the purpose of seller notes?", "a": "<p>A seller note means the seller accepts part of the price as <b>debt</b> owed by the business — like an earn-out, it’s part of the purchase consideration. It gives the seller a reason to stay involved and help with the transition.</p><p>As a lender, the seller now cares about downside protection: the business needs to run well for the loan instalments (and the full price) to be paid. If the seller stays on to manage the business, they’ll be more risk-averse; if not, they’ll make sure the new management team is well prepared.</p>", "p": 89}, {"id": "mna-u2-41", "q": "How are seller notes in M&A modeled?", "a": "<p>Like any other debt. They appear in Sources &amp; Uses as a <b>source</b> of funds, since they help finance the deal. They’re usually subordinated debt with a high fixed interest rate, reflecting their junior position, and often come with a PIK option or a conversion feature.</p>", "p": 89}, {"id": "mna-u2-42", "q": "What is the purpose of the working capital peg negotiation in M&A?", "a": "<p>The peg is the agreed “normal” level of net working capital the business must have at closing — the amount needed to operate on an ongoing basis.</p><p>For the buyer, it stops the seller from pulling cash out by running working capital down before closing, so the business can keep operating without the buyer having to inject more capital.</p>", "p": 89}, {"id": "mna-u2-43", "q": "Can you name a scenario when the post-deal EPS accretion/dilution would not be a significant consideration?", "a": "<p>When a large public company buys a small start-up mainly as an <b>acqui-hire</b>. The focus is on bringing on the key people and the IP; given the size difference, the effect on the acquirer’s EPS is negligible.</p>", "p": 89}]}]}};
window.IBZY_MCQS_EXTRA = (window.IBZY_MCQS_EXTRA||[]).concat([{"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l1", "d": "F", "q": "A 'merger of equals' typically involves:", "o": ["A large company buying a much smaller one for cash", "Two similarly sized companies combining, usually with stock", "A company selling a division", "A private company going public"], "a": 1, "e": "Mergers usually combine similar-sized firms with at least partial stock consideration."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l1", "d": "F", "q": "A merger between two direct competitors is a:", "o": ["Vertical merger", "Horizontal merger", "Conglomerate merger", "Reverse merger"], "a": 1, "e": "Horizontal mergers combine companies in the same market, reducing competition."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l1", "d": "C", "q": "A car manufacturer buying a tyre supplier is an example of:", "o": ["Forward integration", "Backward integration", "Horizontal integration", "A conglomerate merger"], "a": 1, "e": "Buying a supplier moves upstream — backward integration."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l1", "d": "F", "q": "Which is a COST synergy?", "o": ["Cross-selling products", "Closing redundant facilities", "Entering new geographies", "Bundling products"], "a": 1, "e": "Eliminating overlapping facilities and staff reduces costs."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l1", "d": "C", "q": "Strategic buyers can often pay more than financial buyers mainly because:", "o": ["They have more cash", "They can realise synergies", "They pay no tax", "They use more debt"], "a": 1, "e": "Synergies let strategics justify higher premiums (though PE add-ons narrow the gap)."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l1", "d": "C", "q": "Premiums paid analysis uses:", "o": ["The target's DCF", "Average premiums from comparable past deals as a reference", "The acquirer's P/E", "Book value"], "a": 1, "e": "Historical premiums sanity-check the premium in the current deal."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l1", "d": "F", "q": "In a broad auction, the sell-side bank:", "o": ["Contacts one buyer", "Contacts as many potential buyers as possible to maximise competition", "Never shares information", "Only contacts PE firms"], "a": 1, "e": "More bidders tends to raise the final price."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l1", "d": "C", "q": "A tax-related reason to acquire a company is that the target has:", "o": ["High revenue", "Net operating losses (NOLs)", "A strong brand", "Lots of employees"], "a": 1, "e": "NOLs can reduce the combined company's future taxes."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l2", "d": "F", "q": "A negotiated sale is most appropriate when:", "o": ["The seller wants the widest possible auction", "The seller has a specific buyer in mind and values speed and confidentiality", "The company is bankrupt", "Regulators require it"], "a": 1, "e": "It involves few buyers and is faster and more private."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l2", "d": "C", "q": "A common reason M&A deals destroy value is:", "o": ["Underestimating synergies", "Overpaying for expected synergies that don't materialise", "Doing too much due diligence", "Paying no premium"], "a": 1, "e": "Overpaying and overestimating synergies go hand in hand."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l2", "d": "C", "q": "Why do companies keep doing M&A even though many deals destroy value?", "o": ["Deals are always profitable", "Many deals are defensive — protecting market share and acquiring new capabilities", "Regulators require it", "To lower taxes only"], "a": 1, "e": "Incumbents use M&A to fend off threats and keep up with disruption."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l2", "d": "F", "q": "A teaser is:", "o": ["A 50-page detailed report", "A short, anonymous 1–2 page document to gauge buyer interest", "The final purchase agreement", "A regulatory filing"], "a": 1, "e": "It aims to get buyers to sign an NDA for the CIM."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l2", "d": "F", "q": "A buyer typically receives the CIM after:", "o": ["Closing", "Signing an NDA", "Submitting a binding offer", "Receiving regulatory approval"], "a": 1, "e": "The CIM contains confidential information, so an NDA comes first."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l2", "d": "C", "q": "A letter of intent is usually:", "o": ["Binding and final", "Non-binding, setting out proposed price, consideration and financing", "A marketing document", "Filed with the SEC"], "a": 1, "e": "It previews deal terms but leaves room for negotiation."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l2", "d": "C", "q": "A no-shop provision mainly protects:", "o": ["The seller", "The buyer, by giving it exclusivity", "Regulators", "Lenders"], "a": 1, "e": "The seller can't solicit other bids during negotiations."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l2", "d": "A", "q": "A reverse termination fee is paid by:", "o": ["The seller if it walks away", "The buyer if it walks away", "The bank", "Regulators"], "a": 1, "e": "It protects the seller against the buyer abandoning the deal."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l3", "d": "C", "q": "In an asset sale, the buyer benefits because:", "o": ["The seller is taxed once", "The assets get a stepped-up tax basis, creating deductible D&A", "No assets are transferred", "It avoids all liabilities automatically"], "a": 1, "e": "The step-up creates future tax savings for the buyer."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l3", "d": "C", "q": "In a stock sale, the seller is typically taxed:", "o": ["Twice", "Only at the shareholder level", "Not at all", "Only at the corporate level"], "a": 1, "e": "Stock sales avoid the corporate-level tax hit."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l3", "d": "A", "q": "A 338(h)(10) election is:", "o": ["An asset sale for legal purposes", "Legally a stock sale but treated as an asset sale for tax", "A type of hostile takeover", "A filing for 5% stakes"], "a": 1, "e": "It combines stock-sale simplicity with the asset-sale step-up."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l3", "d": "F", "q": "A hostile acquirer publicly offering shareholders a premium for their shares is making a:", "o": ["Proxy fight", "Tender offer", "Spin-off", "Reverse merger"], "a": 1, "e": "A tender offer goes directly to shareholders."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l3", "d": "F", "q": "A poison pill works by:", "o": ["Selling the company's best assets", "Letting existing shareholders buy discounted shares, diluting the acquirer", "Paying executives large bonuses", "Merging with a friendly buyer"], "a": 1, "e": "Dilution makes a majority stake much harder to reach."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l3", "d": "C", "q": "A friendly buyer that acquires the target to block a hostile bidder is a:", "o": ["White knight", "White squire", "Black knight", "Pac-Man"], "a": 0, "e": "A white knight buys the whole company; a white squire buys a partial stake."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l3", "d": "C", "q": "In the Pac-Man defence, the target:", "o": ["Sells its crown jewels", "Tries to acquire the hostile bidder", "Issues new shares to everyone", "Staggers its board"], "a": 1, "e": "It turns the tables, mainly as a deterrent."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l3", "d": "C", "q": "A staggered board defends against takeovers by:", "o": ["Lowering the share price", "Preventing the whole board from being replaced in a single election", "Issuing debt", "Paying greenmail"], "a": 1, "e": "It takes several election cycles to win control."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l4", "d": "F", "q": "Selling a business segment outright is a:", "o": ["Spin-off", "Divestiture", "Carve-out", "Reverse merger"], "a": 1, "e": "A divestiture sells the unit and its assets."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l4", "d": "C", "q": "In an equity carve-out, the parent typically:", "o": ["Sells 100% of the subsidiary", "Sells a minority stake to the public and keeps control", "Gives shares to existing shareholders for free", "Merges with a shell"], "a": 1, "e": "It's a 'partial IPO' — the parent usually keeps over 50%."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l4", "d": "C", "q": "In a spin-off, the new company's shares go to:", "o": ["The highest bidder", "Existing shareholders, pro rata", "The parent's lenders", "Management only"], "a": 1, "e": "Shareholders receive the new shares in proportion to their holdings; no cash is raised."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l4", "d": "F", "q": "A parent owning 30% of another company has a(n):", "o": ["Subsidiary", "Affiliate", "Spin-off", "Carve-out"], "a": 1, "e": "Minority ownership makes it an affiliate."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l4", "d": "C", "q": "The main benefit of a reverse merger is:", "o": ["Higher taxes", "Becoming public without a traditional IPO", "Avoiding all regulation", "Gaining a control premium"], "a": 1, "e": "The private company merges into an already-listed entity."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l4", "d": "C", "q": "An investor with 6% of a company who intends to seek influence must file:", "o": ["Schedule 13-G", "Schedule 13-D", "Form S-4", "Form 8-K"], "a": 1, "e": "13-D is required for 5%+ holders with active intent."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l4", "d": "F", "q": "The 'winner's curse' refers to:", "o": ["The losing bidder's costs", "The winning bidder overpaying relative to fair value", "Regulatory fines", "A tax penalty"], "a": 1, "e": "Competitive bidding can push prices above fair value."}, {"t": "M&A", "u": "M&A · M&A Concepts", "l": "mna-u1-l4", "d": "C", "q": "A holdback in M&A:", "o": ["Delays the deal announcement", "Places part of the purchase price in escrow to protect the buyer", "Is a defence against takeovers", "Is a type of debt"], "a": 1, "e": "Funds can go to the buyer if the seller breaches the agreement."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l1", "d": "F", "q": "The central question an M&A model answers is usually:", "o": ["What is the target's beta?", "Will the deal be accretive or dilutive to the acquirer's EPS?", "What is the risk-free rate?", "How much inventory does the target hold?"], "a": 1, "e": "Combining the income statements produces pro forma EPS vs. standalone EPS."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l1", "d": "F", "q": "A deal is accretive when:", "o": ["Pro forma EPS > acquirer's standalone EPS", "Pro forma EPS < standalone EPS", "The target has debt", "The premium is above 20%"], "a": 0, "e": "Accretion means the combined EPS is higher than the acquirer's own."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l1", "d": "C", "q": "Does an accretive deal always create value?", "o": ["Yes, always", "No — long-term value depends on the combined company's intrinsic value", "Only if paid in cash", "Only if there are no synergies"], "a": 1, "e": "EPS accretion is a short-term accounting effect, not proof of value creation."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l1", "d": "C", "q": "On a cash-free, debt-free basis, the buyer is effectively paying for the target's:", "o": ["Equity value", "Enterprise value", "Book value", "Cash balance"], "a": 1, "e": "The seller keeps excess cash and repays debt, so the price reflects EV."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l1", "d": "C", "q": "An all-stock deal is generally attractive to target shareholders who want to:", "o": ["Lock in a guaranteed value", "Defer tax and share in future upside", "Avoid owning the combined company", "Receive immediate cash"], "a": 1, "e": "Stock defers the taxable event and keeps exposure to the combined company."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l1", "d": "A", "q": "Under a FIXED exchange ratio, if the acquirer's share price falls after signing:", "o": ["Target holders receive more shares", "Target holders receive the same number of shares, so the deal is worth less to them", "The deal is cancelled", "The acquirer pays cash instead"], "a": 1, "e": "Fixed ratios lock the share count, leaving target holders exposed to price falls."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l1", "d": "C", "q": "A floating exchange ratio protects target shareholders because:", "o": ["It's paid in cash", "It fixes the dollar value per share, issuing more acquirer shares if the price falls", "It removes taxes", "It caps synergies"], "a": 1, "e": "The value received stays constant; the share count adjusts."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l1", "d": "F", "q": "A key benefit to an acquirer of paying with stock is that it:", "o": ["Raises cash", "Preserves cash and avoids new debt", "Always increases EPS", "Eliminates goodwill"], "a": 1, "e": "Stock consideration conserves the buyer's cash."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l2", "d": "C", "q": "All-cash deals usually carry a higher price than all-stock deals because:", "o": ["Cash is taxed less", "Stock lets sellers share in future upside, so they accept a lower headline price", "Stock deals have no premium", "Cash deals have synergies"], "a": 1, "e": "Fixed, capped cash proceeds require a higher price to compensate."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l2", "d": "C", "q": "In an all-stock deal with no synergies, the deal is dilutive when:", "o": ["The acquirer's P/E is higher than the target's", "The acquirer's P/E is lower than the price-implied P/E of the target", "Both P/Es are equal", "The target has more cash"], "a": 1, "e": "A low-P/E acquirer must issue many shares per dollar of earnings acquired."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l2", "d": "C", "q": "Acquirer P/E 20x, target P/E 13x, 20% premium, all stock. Year 1 is:", "o": ["Dilutive", "Accretive", "Breakeven", "Impossible to say"], "a": 1, "e": "13 × 1.2 = 15.6x < 20x, so it's accretive."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l2", "d": "F", "q": "Offer value equals:", "o": ["Offer price per share × fully diluted shares", "Offer price × basic shares only", "EV − cash", "Net income × P/E"], "a": 0, "e": "Use the fully diluted share count."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l2", "d": "F", "q": "Offer $30/share vs. unaffected price $24. The control premium is:", "o": ["20%", "25%", "30%", "6%"], "a": 1, "e": "30 ÷ 24 − 1 = 25%."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l2", "d": "C", "q": "Why use the 'unaffected' share price for the premium?", "o": ["It's always higher", "Leaks and rumours may already have moved the current price", "It's required by GAAP", "It includes dividends"], "a": 1, "e": "The premium should be measured against the price before deal news."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l2", "d": "F", "q": "Transaction value equals:", "o": ["Offer value + target net debt", "Offer value − net debt", "Offer value × premium", "Net income × P/E"], "a": 0, "e": "It's the target's implied enterprise value."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l2", "d": "C", "q": "In an M&A model, how are transaction fees treated?", "o": ["Capitalised and amortised", "Expensed, reducing equity", "Added to goodwill", "Ignored"], "a": 1, "e": "Advisory, legal and accounting fees are expensed."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l2", "d": "A", "q": "How are financing fees treated?", "o": ["Expensed immediately", "Capitalised as a contra-liability and amortised over the debt term within interest expense", "Added to revenue", "Ignored"], "a": 1, "e": "Debt issuance costs are amortised over the loan's life."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l3", "d": "C", "q": "An acquirer paid $100m (including $40m goodwill) and now values the business at $70m. The goodwill impairment is:", "o": ["$40m", "$30m", "$70m", "$10m"], "a": 1, "e": "$100m − $70m = $30m, leaving $10m of goodwill."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l3", "d": "F", "q": "Which assets are most commonly written up to fair value in a deal?", "o": ["Cash and receivables", "PP&E and intangible assets", "Accounts payable", "Common stock"], "a": 1, "e": "They're often carried well below market value."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l3", "d": "F", "q": "A fairness opinion is provided to:", "o": ["The buyer's lenders", "The seller's board, by the seller's bank", "Regulators", "The acquirer's employees"], "a": 1, "e": "It gives an independent view that the deal terms are fair."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l3", "d": "C", "q": "40% margin, 25% tax. $100 of revenue synergies adds how much net income?", "o": ["$75", "$30", "$40", "$100"], "a": 1, "e": "100 × 40% × 75% = $30."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l3", "d": "C", "q": "$100 of cost synergies at a 25% tax rate adds how much net income?", "o": ["$25", "$75", "$100", "$30"], "a": 1, "e": "Cost savings drop straight through: 100 × 75% = $75."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l3", "d": "C", "q": "Which synergies are acquirers more likely to actually achieve?", "o": ["Revenue synergies", "Cost synergies", "Neither ever happens", "Both equally"], "a": 1, "e": "Cost cuts are specific and controllable; revenue gains are uncertain."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l3", "d": "F", "q": "Why are sell-side mandates usually shorter than buy-side ones?", "o": ["Sellers pay more", "Once a seller commits, buyers are easy to find and deals usually close", "Buy-side deals are illegal", "Sell-side has no due diligence"], "a": 1, "e": "Buy-side searches often drag on and may not result in a deal."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l3", "d": "C", "q": "Financing fees on acquisition debt appear on the balance sheet as:", "o": ["An asset in PP&E", "A contra-liability reducing the debt balance", "Goodwill", "Revenue"], "a": 1, "e": "They're shown as debt issuance costs netted against the debt."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l4", "d": "F", "q": "Incremental D&A in an M&A deal comes from:", "o": ["New revenue", "Writing up the target's assets to fair value", "Transaction fees", "Higher taxes"], "a": 1, "e": "Higher asset values mean more depreciation and amortisation."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l4", "d": "C", "q": "In a stock sale, use of the target's NOLs by the acquirer is limited annually by:", "o": ["Section 338", "Section 382: long-term tax-exempt rate × equity purchase price", "50% of revenue", "The target's EBITDA"], "a": 1, "e": "IRC Section 382 caps annual NOL usage after an ownership change."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l4", "d": "C", "q": "In an asset sale, unused target NOLs:", "o": ["Transfer fully to the acquirer", "Are lost after offsetting the seller's gain", "Double in value", "Become goodwill"], "a": 1, "e": "The acquirer doesn't inherit remaining NOLs in an asset sale."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l4", "d": "A", "q": "DTLs are created in a stock sale because:", "o": ["Tax basis is stepped up but book basis isn't", "Book basis is written up but tax basis isn't, so book depreciation exceeds tax depreciation", "Revenue rises", "Debt is refinanced"], "a": 1, "e": "The book/tax mismatch means book taxes are lower than cash taxes going forward."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l4", "d": "C", "q": "Deferred revenue write-downs are especially common in acquisitions of:", "o": ["Utilities", "Subscription software companies", "Banks", "Oil producers"], "a": 1, "e": "Software deferred revenue is revalued to fair value in purchase accounting."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l4", "d": "F", "q": "An earn-out is:", "o": ["A fee paid to bankers", "Part of the price paid later only if the business hits agreed targets", "A type of debt", "A takeover defence"], "a": 1, "e": "It's contingent consideration used to bridge valuation gaps."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l4", "d": "C", "q": "An earn-out is typically used when:", "o": ["Both sides agree exactly on price", "The seller wants a higher price than the buyer will pay upfront", "The deal is all-stock", "The target is bankrupt"], "a": 1, "e": "Deferring part of the price helps close the valuation gap."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l4", "d": "C", "q": "Who bears the risk of underperformance in an earn-out?", "o": ["The buyer", "The seller", "The bank", "Regulators"], "a": 1, "e": "If targets are missed, the seller doesn't receive the deferred payment."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l5", "d": "F", "q": "Earn-outs most commonly last:", "o": ["1–5 years", "10–20 years", "A few weeks", "Indefinitely"], "a": 0, "e": "Typical earn-out periods are one to five years, paid in instalments."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l5", "d": "C", "q": "In an 'all-or-nothing' earn-out tier, the seller:", "o": ["Gets paid pro rata", "Gets nothing for that tier unless the target is fully met", "Always gets paid", "Pays the buyer"], "a": 1, "e": "It places more risk and pressure on the seller."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l5", "d": "C", "q": "Why is EBITDA preferred over net income as an earn-out metric?", "o": ["It's always higher", "Net income is easier to manipulate with cost cuts or asset sales", "EBITDA includes taxes", "Net income isn't audited"], "a": 1, "e": "EBITDA better reflects long-term value creation and links directly to valuation multiples."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l5", "d": "A", "q": "If an earn-out payout becomes LESS likely, the acquirer records:", "o": ["A loss", "A gain, as the contingent liability falls", "No entry", "Higher goodwill"], "a": 1, "e": "Lower expected payout reduces the liability, creating a non-operating gain."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l5", "d": "F", "q": "Earn-outs are most prevalent in which industry?", "o": ["Utilities", "Healthcare", "Retail", "Airlines"], "a": 1, "e": "Regulatory and clinical uncertainty make contingent payments common."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l5", "d": "C", "q": "A seller note is:", "o": ["A teaser document", "Part of the price paid as debt owed by the business to the seller", "A takeover defence", "A fee to bankers"], "a": 1, "e": "The seller becomes a lender, aligning incentives post-close."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l5", "d": "C", "q": "In Sources & Uses, a seller note appears as:", "o": ["A use of funds", "A source of funds", "Goodwill", "Excluded"], "a": 1, "e": "It helps finance the purchase price."}, {"t": "M&A", "u": "M&A · Accretion/Dilution Modeling", "l": "mna-u2-l5", "d": "C", "q": "The working capital peg protects the buyer by:", "o": ["Capping synergies", "Ensuring normal working capital is left in the business at closing", "Fixing the exchange ratio", "Paying the seller more"], "a": 1, "e": "It stops the seller draining working capital before closing."}]);
